INSERT INTO `tblproducts` VALUES (1,'iPhone 13 Pro','Apple','Smartphone','A2638','Single SIM',NULL,NULL,NULL,'None','12MP TrueDepth','A15 Bionic','6.1','ProMotion 120Hz, Pro Camera System, Ceramic Shield, MagSafe','Premium flagship with ProMotion display, durable design, and high-performance camera system.','1_1.jpg','1_2.jpg','1_3.jpg',0,250000.00,8.00,NULL,NULL,1,'2024-02-20 00:48:44'),(2,'iPhone 15','Apple','Smartphone','A3090','Single SIM',NULL,NULL,NULL,'None','12MP TrueDepth','A16 Bionic','6.1\" Super Retina XDR OLED','Dynamic Island, 48MP Main Camera, USB-C, Ceramic Shield','Modern iPhone featuring Dynamic Island, versatile 48MP camera, and convenient USB-C charging.','2_1.jpg','2_2.jpg','2_3.jpg',0,0.00,7.00,NULL,NULL,1,'2026-06-07 13:18:16'),(3,'iPhone 16','Apple','Smartphone','A3287','Dual SIM',NULL,NULL,NULL,'None','12MP TrueDepth','A18 Chip','6.1\" Super Retina XDR OLED','Camera Control, Action Button, Apple Intelligence, Ceramic Shield','Powered by the A18 chip with dedicated Camera Control button and next-gen Ceramic Shield protection.','3_1.jpg','3_2.jpg','3_3.jpg',0,0.00,0.00,NULL,NULL,1,'2025-06-04 16:05:14'),(4,'iPhone 16 Pro Max','Apple','Smartphone','A3296','Dual SIM',NULL,NULL,NULL,'None','12MP TrueDepth','A18 Pro Chip','6.9\" Super Retina XDR OLED 120Hz','ProMotion 120Hz, Grade 5 Titanium, 4K 120fps Dolby Vision, 5x Telephoto','Ultimate Pro flagship featuring a massive 6.9-inch display, titanium design, and 4K 120 fps video recording.','4_1.jpg','4_2.jpg','4_3.jpg',0,0.00,0.00,NULL,NULL,1,'2026-05-30 16:31:23'),(5,'Samsung Galaxy F07','Samsung','Smartphone','SM-E075F','Dual SIM',NULL,NULL,NULL,'2TB','8MP','MediaTek Helio G99','6.7\" HD+ PLS LCD 90Hz','5000mAh Battery, 25W Fast Charging, 90Hz Display, IP54 Water Resistance','Budget-friendly smartphone packed with a long-lasting battery, high-resolution main camera, and smooth 90Hz display.','5_1.jpg','5_2.jpg','5_3.jpg',0,0.00,0.00,NULL,NULL,1,'2024-01-13 10:21:20'),(6,'Samsung Galaxy M17 5G','Samsung','Smartphone','SM-M176B','Dual SIM',NULL,NULL,NULL,'1TB','13MP','Exynos 1330','6.7\" FHD+ Super AMOLED 90Hz','50MP OIS Camera, Gorilla Glass Victus, 5G Support, 5000mAh Battery','Reliable mid-range 5G device with a vibrant AMOLED display, optical image stabilization, and durable Gorilla Glass Victus build.','6_1.jpg','6_2.jpg','6_3.jpg',0,0.00,0.00,NULL,NULL,1,'2024-09-06 02:12:32'),(7,'Samsung Galaxy S25 Ultra','Samsung','Smartphone','SM-S938B','Dual SIM',NULL,NULL,NULL,'None','12MP','Snapdragon 8 Elite','6.9\" Dynamic LTPO AMOLED 2X 120Hz','200MP Quad Camera with 5x Telephoto, S-Pen Included, Galaxy AI, Titanium Frame, Gorilla Armor 2','Samsung flagship featuring Snapdragon 8 Elite processor, built-in S-Pen, advanced Galaxy AI capabilities, and 200MP photo system.','7_1.jpg','7_2.jpg','7_3.jpg',0,0.00,0.00,NULL,NULL,1,'2024-09-22 03:58:45'),(8,'Google Pixel 9 Pro','Google','Smartphone','GEC77','Dual SIM',NULL,NULL,NULL,'None','42MP Dual PD','Google Tensor G4','6.3\" LTPO OLED 120Hz','Gemini AI Built-in, Super Res Zoom 30x, 7 Years OS Updates, Temperature Sensor','Compact flagship powered by the Tensor G4 chip, featuring 16GB RAM for advanced on-device AI and pro camera controls.','8_1.jpg','8_2.jpg','8_3.jpg',0,0.00,0.00,NULL,NULL,1,'2025-08-01 13:16:12'),(9,'Google Pixel 8 Pro','Google','Smartphone','GC3VE','Dual SIM',NULL,NULL,NULL,'None','10.5MP Dual PD','Google Tensor G3','6.7\" LTPO OLED 120Hz','Best Take, Magic Editor, Audio Magic Eraser, Built-in Skin Temp Sensor','Premium Google smartphone featuring a bright Super Actua display, triple pro cameras, and AI computational photography.','9_1.jpg','9_2.jpg','9_3.jpg',0,0.00,0.00,NULL,NULL,1,'2024-07-30 06:24:49'),(10,'Google Pixel 7 Pro','Google','Smartphone','GP4BC','Dual SIM',NULL,NULL,NULL,'None','10.8MP Ultrawide','Google Tensor G2','6.7\" LTPO AMOLED 120Hz','50MP Triple Camera with 5x Optical Zoom, Photo Unblur, Macro Focus, Face Unblur','Flagship device featuring the Tensor G2 chip, sleek polished aluminum frame, and telephoto zoom capabilities.','10_1.jpg','10_2.jpg','10_3.jpg',0,0.00,0.00,NULL,NULL,1,'2024-09-20 16:15:30'),(11,'Google Pixel 6','Google','Smartphone','GB7N6','Single SIM',NULL,NULL,NULL,'None','8MP','Google Tensor (1st Gen)','6.4\" AMOLED 90Hz','Unique Camera Bar, Magic Eraser, Real Tone, Titan M2 Security','The phone that introduced Custom Google Silicon with a radical camera redesign and standard-setting image processing.','11_1.jpg','11_2.jpg','11_3.jpg',0,0.00,0.00,NULL,NULL,1,'2025-11-15 14:03:07'),(12,'Nokia G11 Plus','Nokia','Smartphone','TA-1421','Single SIM',NULL,NULL,NULL,'512GB','8MP','Unisoc T606','6.52\" HD+ IPS LCD 90Hz','50MP Dual AI Camera, 3-Day Battery Life, 90Hz Refresh Rate, IP52 Splash Resistance','Durable budget smartphone offering up to 3-day battery life, smooth 90Hz display, and 2 years of Android OS upgrades.','12_1.jpg','12_2.jpg','12_3.jpg',0,0.00,0.00,NULL,NULL,1,'2026-01-15 21:29:09'),(13,'Nokia C21 Plus','Nokia','Smartphone','TA-1433','Single SIM',NULL,NULL,NULL,'256GB','5MP with Flash','Unisoc SC9863A','6.52\" HD+ IPS LCD','Clean Android 11 Go Edition, 13MP Dual Camera, Metal Inner Chassis, Rear Fingerprint Sensor','Entry-level Android device built with an aluminum inner chassis for durability, streamlined performance, and security features.','13_1.jpg','13_2.jpg','13_3.jpg',0,0.00,0.00,NULL,NULL,1,'2026-01-02 17:16:30'),(14,'Nokia C30','Nokia','Smartphone','TA-1357','Single SIM',NULL,NULL,NULL,'256GB','5MP','Unisoc SC9863A','6.82\" HD+ IPS LCD','6000mAh Battery, Large 6.82\" Display, Rear Fingerprint Sensor, Face Unlock','Budget smartphone equipped with a massive 6000mAh battery for long usage and an expansive display for streaming.','14_1.jpg','14_2.jpg','14_3.jpg',0,0.00,0.00,NULL,NULL,1,'2025-04-27 21:55:04'),(15,'Nokia 5.4','Nokia','Smartphone','TA-1340','Single SIM',NULL,NULL,NULL,'512GB','16MP','Snapdragon 662','6.39\" HD+ IPS LCD','48MP Quad Camera, OZO Spatial Audio, 2-Day Battery Life, Nordic Design','